@startuml

class Driver {
  + driverID : int
  + name : string
  + isOnSickLeave : boolean
}

class Bus {
  + licensePlate : string
  + isInRepairShop : boolean
}

class Route {
  + routeNumber : int
}

class Shift {
  + shiftType : ShiftType
}

class Schedule {
  + date : date
}

enum ShiftType {
  Morning
  Afternoon
  Night
}

class CityStaff {}

CityStaff "1" -- "*" Route : defines
CityStaff "1" -- "*" Bus : assigns
CityStaff "1" -- "*" Driver : assigns
CityStaff "1" -- "*" Schedule : posts

Route "1" -- "*" Bus : "assigned to"
Bus "1" -- "*" Route : "serves"

Schedule "1" *-- "1..*" Shift
Schedule "1" -- "1" Route
Schedule "1" -- "1" Driver
Schedule "1" -- "1" Bus

Driver "1" -- "*" Schedule
Bus "1" -- "*" Schedule

@enduml

